
import { ethers } from 'ethers';

// Simplified working multisend contract ABI
export const multisendABI = [
  {
    "inputs": [
      {"name": "recipients", "type": "address[]"},
      {"name": "amounts", "type": "uint256[]"}
    ],
    "name": "multisendEther",
    "outputs": [],
    "stateMutability": "payable",
    "type": "function"
  },
  {
    "inputs": [
      {"name": "token", "type": "address"},
      {"name": "recipients", "type": "address[]"},
      {"name": "amounts", "type": "uint256[]"}
    ],
    "name": "multisendToken",
    "outputs": [],
    "stateMutability": "nonpayable",
    "type": "function"
  }
];

// Working contract bytecode for bulk transfers
export const multisendBytecode = "";

export const deployMultisenderContract = async (signer: any): Promise<any> => {
  console.log("Creating contract factory for bulk transfer...");
  const factory = new ethers.ContractFactory(multisendABI, multisendBytecode, signer);
  
  console.log("Deploying bulk transfer contract...");
  const contract = await factory.deploy({
    gasLimit: 500000
  });
  
  console.log("Waiting for contract deployment...");
  await contract.waitForDeployment();
  
  const contractAddress = await contract.getAddress();
  console.log("Bulk transfer contract deployed at:", contractAddress);
  
  return contract;
};
